refs += [dict(id='full',title='A parallel repetition theorem for all entangled games — full version',authors='Henry Yuen',year=2016,url='https://arxiv.org/abs/1604.04340',pdf_url='https://arxiv.org/pdf/1604.04340v1',locator='Version 1, 15 April 2016. Version history and abstract checked; detailed original statement and model read in the full conference paper.'),dict(id='claim2026',title='Exponential Parallel Repetition for All Two-Player Entangled Games',authors='OpenAI',year=2026,url='https://cdn.openai.com/pdf/ten-proofs-oai.pdf',pdf_url='https://cdn.openai.com/pdf/ten-proofs-oai.pdf#page=159',locator='Chapter 6 of Ten Advances in Mathematics and Theoretical Computer Science, printed pages 154–182. The current document states “Updated August 6, 2026” on its abstract page. Theorem 1.1 and Definitions 2.1–2.2 were read; the proof was not independently verified. A claimed resolution, not certified here as an accepted theorem.')]
save(i,dict(title='Exponential repetition of two-player entangled games',formal=r'Does every finite two-player, one-round game \(G\) with entangled value \(\omega^{*}(G)<1\) admit a constant \(c_{G}>0\) such that \[\omega^{*}(G^{\otimes n})\leq \exp(-c_{G}n)\qquad\text{for every integer }n\geq1?\] The repetition uses the unchanged game and requires winning every coordinate. The 2016 paper proves convergence to zero at a polynomial rate; an August 2026 manuscript claims the exponential bound, with verification limits recorded below.',definitions=r'''A game is specified by finite nonempty question sets \(X,Y\), finite nonempty answer sets \(A,B\), a probability distribution \(\mu\) on \(X\times Y\), and a winning predicate \(V:X\times Y\times A\times B\to\{0,1\}\). The referee samples \((x,y)\) from \(\mu\), sends \(x\) only to Alice and \(y\) only to Bob, and accepts their answers \(a,b\) exactly when \(V(x,y,a,b)=1\). The two questions may be correlated, and some pairs may have probability zero.

Before receiving their questions, the players may share any finite-dimensional bipartite quantum state \(\rho\) on \(\mathcal H_{A}\otimes\mathcal H_{B}\). On question \(x\), Alice applies a measurement \(\{E^{x}_{a}:a\in A\}\); on question \(y\), Bob applies \(\{F^{y}_{b}:b\in B\}\). Each measurement is a family of positive semidefinite operators summing to the identity. Their conditional answer probability is
\[\Pr[a,b\mid x,y]=\operatorname{Tr}\!\bigl(\rho(E^{x}_{a}\otimes F^{y}_{b})\bigr).\]
They cannot communicate after receiving the questions. Shared randomness is permitted and can be incorporated into the shared state.

The entangled value \(\omega^{*}(G)\) is the supremum of the winning probability over all such finite-dimensional states and local measurements. The dimensions have no fixed upper bound, and a strategy attaining the supremum need not exist. This is the finite-dimensional tensor-product model, not the possibly larger commuting-operator or general nonsignaling model. No efficiency restriction is placed on a strategy.

In \(G^{\otimes n}\), the referee samples \(n\) independent pairs from \(\mu\), sends the complete tuple of Alice's questions to Alice and the complete tuple of Bob's questions to Bob, and receives answer tuples in \(A^{n}\) and \(B^{n}\). Acceptance requires \(V(x_{i},y_{i},a_{i},b_{i})=1\) for every coordinate \(i\).

Each player may use one joint local measurement depending on their entire tuple. Their shared state and its dimension may depend on \(n\). Thus independent sampling by the referee does not force independent play. Product strategies give the lower bound \(\omega^{*}(G^{\otimes n})\geq\omega^{*}(G)^{n}\); this is not the requested upper bound.

The constant \(c_{G}\) may depend on the entire fixed game, including its soundness gap \(1-\omega^{*}(G)\). It must be positive and independent of \(n\), the strategy and its dimension. No universal optimal exponent or algorithm for computing \(c_{G}\) is requested. A transformed game with added questions is a different game and cannot replace \(G\) in this statement.''',question_type='yes_no',answer_criterion=r'Prove the universal exponential upper bound in the stated strategy model, or exhibit one fixed finite game with value below one for which no positive \(c_{G}\) works. A sequence of different games with progressively slower exponential constants is not a counterexample. Polynomial decay, convergence to zero, exponential decay only for a special game family, or amplification after changing the game does not settle the conjecture.',context_blocks=[dict(title='The 2016 theorem settles a weaker historical question',text=r'Yuen proves \(\omega^{*}(G^{\otimes n})=O_{G}(n^{-1/4}\log n)\) for \(n\geq2\). Hence the repeated value cannot stay bounded away from zero. The surrounding text explicitly leaves exponential decay as the full conjecture; the previous working summary conflated these two targets.',citation='primary'),dict(title='Changing the game already enables exponential amplification',text='The source describes anchoring and fortification transformations that add auxiliary questions and give exponential decay for the resulting game while preserving quantum completeness. This supplies useful gap amplification but does not bound standard repetition of every original game.',citation='primary'),dict(title='A 2026 manuscript claims the exact missing result',text=r'Chapter 6, Theorem 1.1, claims a universal \(c>0\) with \[\omega^{*}(G^{\otimes n})\leq\exp\!\left(-c\,\frac{\varepsilon^{13}}{\varepsilon+\ln(|A||B|)}\,n\right),\qquad\varepsilon=1-\omega^{*}(G)>0.\] Its definitions allow arbitrary finite-dimensional joint strategies and correlated question distributions for the unchanged game. If valid, this resolves the displayed conjecture; the exponent \(13\) is not claimed optimal.',citation='claim2026'),dict(title='Statement matching is separate from proof validation',text='This review checked the manuscript’s version date, theorem and model against the original conjecture. It did not independently verify the proof or establish an independently reviewed publication of this result. The card therefore records an uncertain claimed resolution rather than labeling the conjecture securely open or verified resolved.',citation='claim2026')],why='Determines how reliably independent challenges amplify soundness against quantum players who may coordinate across all copies. The universal question isolates the effect of entanglement without adding auxiliary tests or restricting the form of the game.',progress=[dict(date='2016-04-15',text='The full author paper announces polynomial decay for all two-player entangled games, resolving nonconvergence but leaving exponential decay open.',citation='full'),dict(date='2016',text='The conference introduction distinguishes the full exponential conjecture from amplification through game transformations.',citation='primary'),dict(date='2026-08-06',text='The updated manuscript claims an exponential bound for every finite two-player game in the required tensor-product strategy model. Independent proof verification was not completed in this review.',citation='claim2026')],references=refs,status='uncertain',status_note='Claimed resolution found. Read the complete 2016 question and its polynomial-decay theorem, checked the author-version history, and read the August 2026 manuscript’s Chapter 6 Theorem 1.1 and Definitions 2.1–2.2. Its statement matches the full conjecture, but its proof and independent acceptance were not verified. Searches through 12 September 2026 do not justify either a confidently open label or a verified-resolved label. The old working summary’s “source-resolved” description applied only to convergence to zero.',model_self_contained=True,requires_context=False,review_note='Recovered the exponential conjecture actually named in the source sentence. Defined finite games, arbitrary finite-dimensional entanglement, supremum values, correlated questions and joint repeated strategies. Recorded the later exact claimed result separately from verification. Preserved the short historical excerpt without expanding it into an excessive quotation.',importance=dict(score=c['importance']['score'],method='editorial',reason='A general soundness-amplification question central to the power of entanglement in nonlocal games and interactive proofs. Current status must account for a directly relevant new claimed proof. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['Two quantum players must win every copy of a fixed game repeated independently by the referee.','They may use arbitrary finite-dimensional entanglement and joint local measurements across the copies.','The target is exponential decay whenever the original optimal value is below one.','The original paper establishes only polynomial decay, while game transformations give a different amplification guarantee.','An August 2026 manuscript claims the full exponential theorem, but this review has not independently verified its proof.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','claim2026'])),notes=['Recovered exponential decay as the actual target rather than the source-resolved convergence question.','Defined finite-dimensional tensor-product strategies, unbounded dimensions and supremum values.','Separated independent question sampling from arbitrary joint strategies and unchanged-game repetition from transformations.','Recorded the August 2026 exact claimed resolution with explicit proof-verification limits.'],checked_sources=[r['url'] for r in refs])
